// Turn the uploaded photos into base64 text so Claude can look at them.
const item = $input.first();
const photos = [];
for (const key of Object.keys(item.binary || {})) {
  const file = item.binary[key];
  const mime = file.mimeType || '';
  if (!mime.startsWith('image/') && mime !== 'application/pdf') continue;
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  photos.push({ name: file.fileName || key, mime, data: buffer.toString('base64') });
}
return [{ json: { ...item.json, photos } }];

const w = $json;
const photos = $('Read photos').first().json.photos || [];

const SYSTEM = "You help a pre-owned luxury watch dealer with a FIRST authenticity screening. You look at photos of serial numbers, case backs, warranty cards and papers. Read the serial and reference numbers you can see, compare them with what the dealer typed, and check that brand, reference, serial range, year and papers are consistent with each other. List every warning sign (wrong fonts, spelling mistakes, mismatched numbers, edited or low-quality papers, serial range not matching the year, etc.). You can never confirm that a watch is genuine: a watchmaker must open and inspect it. If a photo is missing or unclear, say 'unknown' and explain.";
const SCHEMA = {
  "type": "object",
  "properties": {
    "serial_read": {
      "type": "string"
    },
    "reference_read": {
      "type": "string"
    },
    "serial_matches": {
      "type": "string",
      "enum": [
        "yes",
        "no",
        "unknown"
      ]
    },
    "reference_matches": {
      "type": "string",
      "enum": [
        "yes",
        "no",
        "unknown"
      ]
    },
    "papers_consistent": {
      "type": "string",
      "enum": [
        "yes",
        "no",
        "unknown"
      ]
    },
    "risk_flags": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "confidence": {
      "type": "string",
      "enum": [
        "low",
        "medium",
        "high"
      ]
    },
    "notes": {
      "type": "string"
    }
  },
  "required": [
    "serial_read",
    "reference_read",
    "serial_matches",
    "reference_matches",
    "papers_consistent",
    "risk_flags",
    "confidence",
    "notes"
  ],
  "additionalProperties": false
};
const userContent = [
  ...photos.map(p => p.mime === 'application/pdf'
      ? { type: 'document', source: { type: 'base64', media_type: p.mime, data: p.data } }
      : { type: 'image', source: { type: 'base64', media_type: p.mime, data: p.data } }),
  { type: 'text', text:
`The dealer entered:
Brand: ${w.brand}
Model: ${w.model || '-'}
Reference: ${w.reference}
Serial number: ${w.serial_number || '-'}
Year: ${w.year || '-'}
Box and papers: ${w.box_papers ? 'yes' : 'no'}
Photos attached: ${photos.length ? photos.map(p => p.name).join(', ') : 'none'}

Check these details and the photos.` },
];

return {
  json: {
    claude_request: {
      model: 'claude-opus-5',
      max_tokens: 16000,
      fallbacks: 'default',              // if the model declines, Anthropic retries on a fallback model
      system: SYSTEM,
      messages: [{ role: 'user', content: userContent }],
      output_config: {
        effort: 'high',             // low / medium / high: more effort = better answers, more cost
        format: { type: 'json_schema', schema: SCHEMA },
      },
    },
  },
};

// Read Claude's answer. The answer is JSON because we asked for a JSON schema.
const res = $json;
if (res.stop_reason === 'refusal') {
  throw new Error('Claude declined this request: ' + JSON.stringify(res.stop_details || {}));
}
const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
if (!text) {
  throw new Error('Claude returned no text: ' + JSON.stringify(res).slice(0, 500));
}
const ai = JSON.parse(text);

return [{ json: { watch_id: $('Save watch').first().json.id, ...ai } }];

// Make text safe to put inside an HTML email
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (n) => n == null || n === '' ? '-' : '$' + Math.round(Number(n)).toLocaleString('en-US');

const w = $json;
const a = $('Read authenticity answer').first().json;
const flags = a.risk_flags.length
  ? '<ul>' + a.risk_flags.map(f => `<li>${esc(f)}</li>`).join('') + '</ul>'
  : '<p>No warning signs seen in the photos.</p>';
return [{
  json: {
    owner_email: w.owner_email,
    from_email: w.from_email,
    subject: `Stock #${w.id}: ${w.brand} ${w.reference} - AI check ${a.risk_flags.length ? 'found ' + a.risk_flags.length + ' warning(s)' : 'OK'}`,
    html: `<h3>${esc(w.brand)} ${esc(w.model)} ${esc(w.reference)} (stock #${w.id})</h3>
<p>Serial typed: <b>${esc(w.serial_number)}</b> | read on photo: <b>${esc(a.serial_read)}</b> (match: ${esc(a.serial_matches)})<br>
Reference read on photo: <b>${esc(a.reference_read)}</b> (match: ${esc(a.reference_matches)})<br>
Papers consistent: ${esc(a.papers_consistent)} | AI confidence: ${esc(a.confidence)}</p>
<h4>Warning signs</h4>${flags}
<p>${esc(a.notes)}</p>
<p>Suggested price: <b>${money(w.suggested_price_usd)}</b> | Asking price: <b>${money(w.ask_usd)}</b> | Cost: ${money(w.cost_usd)}</p>
<p style="color:#b00"><b>This is only a first screening.</b> A watchmaker must inspect the watch and record the result
with the "Watchmaker verdict" form.</p>`,
  },
}];
